! function(e, n, t) {
    console.log("init");
    var o = {
        init: function(t) { o.select2(), o.owlCarousel(), o.portfolio(), o.lightCase(), o.counter(), o.scrollTo(), o.navbarChange() },
        select2: function() { e(t).ready(function() { e("select").select2() }) },
        owlCarousel: function() { e(".slideshow").owlCarousel({ loop: !0, items: 1, nav: !0, navSpeed: 1e3, dots: !0, dotSpeed: 1e3, autoplay: !0, autoplaySpeed: 1e3, autoplayTimeout: 5e3, navText: ['<span class="icon-nav-slider nav-left"></span>', '<span class="icon-nav-slider nav-right"></span>'] }) },
        portfolio: function() {
            var n = e(".grid-portfolio").isotope({ itemSelector: ".grid-item", masonry: { gutter: ".gutter-sizer", columnWidth: ".grid-sizer" }, percentPosition: !0 });
            return e(".filter-button-group").on("click", "a", function() {
                var t = e(this).attr("data-filter");
                n.isotope({ filter: t })
            }), e(".btn-filter a.is-checked").addClass("active"), e(".btn-filter a").on("click", function() { e(".btn-filter a").removeClass("active"), e(this).addClass("active") }), !1
        },
        lightCase: function() { jQuery(t).ready(function(t) { t("a[data-rel^=lightcase]").lightcase() }) },
        counter: function() { e("#counter").each(function() { e(this).waypoint({ handler: function(t) { e(".number").countTo({ speed: 1e3 }), this.destroy() }, offset: "80%" }) }) },
        scrollTo: function() {
            e("#navbar-nav-header .nav-link").on("click", function(t) {
                var n, o = e(this).attr("href");
                n = "#home" !== o ? e(o).offset().top - 50 : 0, e("html, body").animate({ scrollTop: n }, 750), t.preventDefault()
            })
        },
        navbarChange: function() { e(n).scroll(function() { var t = e(n).scrollTop(); return 150 < t ? (e("nav").removeClass("navbar-transparent"), e("body").addClass("not-on-top")) : (e("body").removeClass("not-on-top"), e("nav").addClass("navbar-transparent")), !1 }) }
    };
    e(t).ready(function() { o.init(e) })
}(window.jQuery, window, document);


function openCity(evt, cityName) {
    console.log("here")
        // Declare all variables
    var i, tabcontent, tablinks;

    // Get all elements with class="tabcontent" and hide them
    tabcontent = document.getElementsByClassName("tabcontent");
    for (i = 0; i < tabcontent.length; i++) {
        tabcontent[i].style.display = "none";
    }

    // Get all elements with class="tablinks" and remove the class "active"
    tablinks = document.getElementsByClassName("tablinks");
    for (i = 0; i < tablinks.length; i++) {
        tablinks[i].className = tablinks[i].className.replace(" active", "");
    }

    // Show the current tab, and add an "active" class to the button that opened the tab
    document.getElementById(cityName).style.display = "block";
    evt.currentTarget.className += " active";
}